Section: ES: Expressions and statements

Rule: ES.65: Don’t dereference an invalid pointer

Reason: Dereferencing an invalid pointer, such as 
nullptr
, is undefined behavior, typically leading to immediate crashes,
wrong results, or memory corruption.

Example:
void f()
{
    int x = 0;
    int* p = &x;

    if (condition()) {
        int y = 0;
        p = &y;
    } // invalidates p

    *p = 42;            // BAD, p might be invalid if the branch was taken
}

void f1()
{
    int x = 0;
    int* p = &x;

    int y = 0;
    if (condition()) {
        p = &y;
    }

    *p = 42;            // OK, p points to x or y and both are still in scope
}

Example:
void f(int* p)
{
    int x = *p; // BAD: how do we know that p is valid?
}

void f1(int* p) // deal with nullptr
{
    if (!p) {
        // deal with nullptr (allocate, return, throw, make p point to something, whatever)
    }
    int x = *p;
}

void f2(int* p) // state that p is not supposed to be nullptr
{
    assert(p);
    int x = *p;
}

void f3(int* p) // state that p is not supposed to be nullptr
    [[expects: p]]
{
    int x = *p;
}

void f(not_null<int*> p)
{
    int x = *p;
}

